async function verifyNginxSite() {
  const response = await fetch(`${BASE_URL}/version.json`, { cache: 'no-store' })
  assert.ok(response.ok, `nginx version.json returned HTTP ${response.status}`)
  const version = await response.json()
  assert.equal(version.env, 'production', `unexpected build environment: ${version.env}`)
  const expectedBranch = process.env.E2E_EXPECTED_BRANCH
  if (expectedBranch) assert.equal(version.gitBranch, expectedBranch, `wrong site branch: ${version.gitBranch}`)
  console.log(`[navbar-visual] nginx build ${version.gitHash} (${version.gitBranch})`)
}
